// Classify the run and only report a CHANGE of state.
//
// Two different fields matter and they fail independently:
//   connected           -> the API session is alive
//   smartphoneConnected -> the phone behind it is reachable
// Session alive with an unreachable phone is the 'degraded' state: sending
// still works, but media downloads quietly start failing.
//
// A node error (onError: continue) also counts as offline on purpose. Not
// being able to ask is not the same as being fine.
const cfg = $('Config').first().json;
const s = $input.first().json || {};

const errored = Boolean(s.error);
const connected = s.connected === true;
const phone = s.smartphoneConnected === true;

let state = 'offline';
if (!errored && connected && phone) state = 'online';
else if (!errored && connected) state = 'degraded';

const store = $getWorkflowStaticData('global');
const previous = store.lastState || 'online';
store.lastState = state;

const changed = state !== previous;
const recovered = changed && state === 'online';

const label = cfg.instanceLabel || 'whatsapp';
const text = recovered
  ? `WhatsApp number "${label}" is back online.`
  : state === 'degraded'
    ? `WhatsApp number "${label}" is degraded: session is alive but the phone is unreachable. Media downloads may fail.`
    : `WhatsApp number "${label}" is OFFLINE. Messages are not being delivered.`;

return [{
  json: {
    state,
    previous,
    shouldAlert: changed,
    recovered,
    text,
    alertWebhookUrl: cfg.alertWebhookUrl,
    raw: { connected, smartphoneConnected: phone, errored },
  },
}];
